// Where each part answers: its port, from a settings file, fixed, or
// another part's; its address and its Open link; and its settings with the
// ports of other parts filled in.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parseEnv } from "node:util";
// The values in a settings (.env) file, or none when it is not there.
export function readSettings(root, file) {
    const path = join(root, file);
    return existsSync(path)
        ? parseEnv(readFileSync(path, "utf8"))
        : {};
}
export function portOf(part, parts, root) {
    const source = part.port;
    if (!source)
        return null;
    if ("fixed" in source)
        return source.fixed;
    if ("part" in source) {
        const other = parts.find((p) => p.id === source.part);
        return other && other !== part ? portOf(other, parts, root) : null;
    }
    const value = Number(readSettings(root, source.env)[source.key]);
    return Number.isInteger(value) && value > 0 ? value : source.default;
}
export function addressOf(part, parts, root) {
    const port = portOf(part, parts, root);
    return port ? `http://127.0.0.1:${String(port)}` : null;
}
// What the Open link points at, if the part has one.
export function linkOf(part, parts, root) {
    if (!part.open)
        return null;
    if (/^https?:/.test(part.open))
        return part.open;
    const address = addressOf(part, parts, root);
    return address ? `${address}${part.open}` : null;
}
// The part's settings with "{port:<part>}" replaced by that part's port.
export function envOf(part, parts, root) {
    if (!part.env)
        return undefined;
    return Object.fromEntries(Object.entries(part.env).map(([key, value]) => [
        key,
        value.replace(/\{port:([\w-]+)\}/g, (_match, id) => {
            const other = parts.find((p) => p.id === id);
            return String((other && portOf(other, parts, root)) ?? "");
        }),
    ]));
}
